corrected_code:
@login_required
def download_confidential_page_attachment(request, page_id, doc_id):
    page = get_object_or_404(Page, id=page_id).specific
    page_perms = page.permissions_for_user(request.user)
    restriction = page.get_view_restrictions().first()
    if restriction and not restriction.accept_runner(request):
        raise PermissionDenied("You do not have clearance to view this restricted page.")
    doc = get_object_or_404(page.confidential_documents, id=doc_id)
    return FileResponse(doc.file.open('rb'), as_attachment=True, filename=doc.filename)
